/*
 * Ownership and callback contract:
 * - Opaque handles are generation-checked and thread-affine.
 * - destroy functions release only the named opaque handle; removing a node
 *   from the retained tree is an explicit divui_element_remove operation.
 * - Every DivUiUtf8 and byte slice is copied or consumed synchronously; it need
 *   only remain readable through the call.
 * - Event callbacks run synchronously without an internal engine borrow and
 *   may reenter any API on the owning thread. The callback and user_data must
 *   remain valid until its DivUiListener is destroyed.
 * - Setting DIVUI_EVENT_DEFAULT_PREVENTED or DIVUI_EVENT_PROPAGATION_STOPPED in a
 *   callback updates dispatch state; callbacks must not retain DivUiEvent*.
 * - DIVUI_EVENT_IMMEDIATE_PROPAGATION_STOPPED also stops remaining listeners in
 *   the current invocation, including Rust listeners on the shared route.
 * - Accessibility snapshots own their nodes and strings. A snapshot remains
 *   readable after its document is destroyed, on the snapshot's owning thread.
 *   Destroy each snapshot after use. Output strings are raw UTF-8 bytes without
 *   a terminator. The first copy call may use NULL and zero capacity to query
 *   the required length or count.
 */

uint32_t divui_abi_version(void);
DivUiStatus divui_error_get_last(DivUiErrorInfo* out_error);
DivUiStatus divui_error_copy_message(uint8_t* destination, size_t capacity, size_t* out_length);

